/**
 * lib/commands.ts — Telegram management command definitions
 * ========================================================
 * 88+ commands across 10 categories for managing Telegram accounts.
 * Each command has input schema and executor function.
 */

export interface CommandParam {
  name: string;
  label: string;
  type: 'text' | 'number' | 'phone' | 'select' | 'textarea' | 'checkbox';
  required: boolean;
  placeholder?: string;
  options?: { label: string; value: string }[];
  defaultValue?: string | number | boolean;
  help?: string;
}

export interface CommandDef {
  id: string;
  name: string;
  label: string;
  description: string;
  category: CommandCategory;
  icon: string;
  params: CommandParam[];
  requiresAccount: boolean;
  danger?: 'low' | 'medium' | 'high';
}

export type CommandCategory =
  | 'account'
  | 'profile'
  | 'messages'
  | 'contacts'
  | 'groups'
  | 'channels'
  | 'privacy'
  | 'security'
  | 'automation'
  | 'utilities'
  | 'scraping'
  | 'mass'
  | 'op3'        // OP3 Adders
  | 'ramex'      // Ramex Adders
  | 'nearby'     // Nearby + countries
  | 'messaging'  // Messaging + sub-options
  | 'reports'    // Reports + types
  | 'engagement' // Engagement
  | 'group_tools' // Group Tools
  | 'account_tools' // Account Tools
  | 'filters'    // 🎯 Filters (10)
  | 'secure_login'; // 🔐 Secure Login

